import "C"

import "unsafe"

// boolToInt converts a Go bool to C.int for use in CGo calls.
func boolToInt(b bool) C.int {
	if b {
		return 1
	}
	return 0
}

// cgo_NewWxString creates a heap-allocated wxString from a Go string.
func cgo_NewWxString(s string) unsafe.Pointer {
	cs := C.CString(s)
	defer C.free(unsafe.Pointer(cs))
	return C.wxString_CreateUTF8(cs)
}

// cgo_FreeWxString deletes a wxString allocated by the C++ side.
func cgo_FreeWxString(ptr unsafe.Pointer) { C.wxString_Delete(ptr) }

// cgo_WxStringToGoAndFree extracts a Go string from a wxString pointer
// via a transient UTF-8 buffer, then frees both objects.
func cgo_WxStringToGoAndFree(ptr unsafe.Pointer) string {
	buf := C.kwxUtf8Buffer_Create(ptr)
	s := C.GoString(C.kwxUtf8Buffer_Data(buf))
	C.kwxUtf8Buffer_Delete(buf)
	C.wxString_Delete(ptr)
	return s
}

